\ce{H2PO4- + H2O &lt;=&gt; HPO4^{2-} + H3O+}
\] \[
\begin{split}
&\ce{H2PO4}^{-}\\
C_i &= 0.0476\ M \\
\Delta C &= - x\ M \\
C_f &= 0.0476 - x\ M \\
\end{split}
\qquad
\begin{split}
&\ce{HPO4}^{2-}\\
C_i &= 0\ M \\
\Delta C &= + x\ M \\
C_f &= x\ M \\
